import{_ as e,o,c as n,a1 as a}from"./chunks/framework.COskihg7.js";const g=JSON.parse('{"title":"Share Internet with Consoles and Other Devices","description":"","frontmatter":{},"headers":[],"relativePath":"guide/non-app-devices.md","filePath":"guide/non-app-devices.md"}'),r={name:"guide/non-app-devices.md"};function i(s,t,d,h,l,c){return o(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="share-internet-with-consoles-and-other-devices" tabindex="-1">Share Internet with Consoles and Other Devices <a class="header-anchor" href="#share-internet-with-consoles-and-other-devices" aria-label="Permalink to &quot;Share Internet with Consoles and Other Devices&quot;">​</a></h1><p>A PS4, PS5, Xbox, smart TV, or other device can use the Android host without installing an app. A Windows 10/11 laptop acts as the bridge:</p><p><code>Android SOCKS5 host -&gt; Windows VPN tunnel -&gt; Windows Internet Connection Sharing -&gt; console</code></p><p>The phone&#39;s Wi-Fi Direct connection is a SOCKS5 proxy, so connecting a console directly to it does not provide a normal internet connection. The Windows client creates a VPN adapter and shares that adapter over one selected Ethernet port or Windows Mobile Hotspot.</p><h2 id="before-you-start" tabindex="-1">Before You Start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before You Start&quot;">​</a></h2><ol><li>Start <strong>Share (Host)</strong> on the Android phone.</li><li>Connect the Windows laptop to the phone&#39;s Wi-Fi Direct network.</li><li>Run the <a href="/Hotspot-Bypass-VPN-Unlimited-Hotspot/guide/windows">Windows client</a> as Administrator and click <strong>Connect VPN</strong>. Wait for <strong>Connected</strong>.</li><li>For Ethernet, connect the console to a laptop Ethernet port or USB Ethernet adapter. For Wi-Fi, the laptop must support Mobile Hotspot while connected to the phone.</li></ol><h2 id="ethernet-cable" tabindex="-1">Ethernet Cable <a class="header-anchor" href="#ethernet-cable" aria-label="Permalink to &quot;Ethernet Cable&quot;">​</a></h2><ol><li>Select <strong>Ethernet cable</strong> in <strong>Share with consoles &amp; devices</strong>.</li><li>Connect the cable, click <strong>Refresh</strong>, and select the connected Ethernet adapter.</li><li>Click <strong>Start Sharing Network</strong> and wait for the success message.</li><li>Set up a wired connection on the console. Keep IP and DNS automatic, and leave proxy settings off.</li><li>Test the console connection, then try a download and an online game.</li></ol><h2 id="wi-fi-hotspot" tabindex="-1">Wi-Fi Hotspot <a class="header-anchor" href="#wi-fi-hotspot" aria-label="Permalink to &quot;Wi-Fi Hotspot&quot;">​</a></h2><ol><li>Leave the default <strong>Wi-Fi hotspot</strong> method selected in <strong>Share with consoles &amp; devices</strong> and click <strong>Start Sharing Network</strong>.</li><li>Wait for confirmation that the hotspot and sharing are active. Join the displayed network using the displayed password. You can also find them under <strong>Windows Settings &gt; Network &amp; internet &gt; Mobile hotspot</strong>.</li><li>Keep the console&#39;s IP and DNS automatic, and leave proxy settings off.</li><li>Test the console connection, then try a download and an online game.</li></ol><p>If the hotspot cannot start or the Wi-Fi adapter cannot stay connected to the phone while hosting, use Ethernet. A second Wi-Fi adapter may also help.</p><h2 id="stop-and-troubleshooting" tabindex="-1">Stop and Troubleshooting <a class="header-anchor" href="#stop-and-troubleshooting" aria-label="Permalink to &quot;Stop and Troubleshooting&quot;">​</a></h2><p>Click <strong>Stop Sharing Network</strong> before stopping the VPN. The client also removes its sharing configuration on VPN stop or tunnel loss and restores the Windows sharing settings it changed. If cleanup fails, retry <strong>Stop Sharing Network</strong> and check the adapter&#39;s <strong>Sharing</strong> tab in Windows Network Connections before closing the app.</p><table tabindex="0"><thead><tr><th>Issue</th><th>What to check</th></tr></thead><tbody><tr><td>Ethernet adapter is missing</td><td>Connect the cable, wait for Windows to show the port as connected, then click <strong>Refresh</strong>.</td></tr><tr><td>Sharing already in use</td><td>The app leaves sharing on unrelated adapters alone. Disable the other sharing first.</td></tr><tr><td>Hotspot will not start</td><td>Check Windows Mobile Hotspot settings, try a second Wi-Fi adapter, or use Ethernet.</td></tr><tr><td>Console has no IP or DNS</td><td>Restart console sharing and reconnect the console.</td></tr><tr><td>Downloads work but games fail</td><td>Mobile-carrier NAT can restrict inbound traffic. Outbound TCP and UDP are forwarded, but NAT Type 2 and every peer-to-peer game cannot be guaranteed.</td></tr></tbody></table><p>A Mac or other computer can also join the Windows bridge. The Windows client itself runs only on Windows.</p>',15)])])}const u=e(r,[["render",i]]);export{g as __pageData,u as default};
